    'msedge.exe': [pf86 + '\\Microsoft\\Edge\\Application\\msedge.exe', pf + '\\Microsoft\\Edge\\Application\\msedge.exe'],
    'firefox.exe': [pf + '\\Mozilla Firefox\\firefox.exe', pf86 + '\\Mozilla Firefox\\firefox.exe'],
